                                "script": {
                                    "apiVersion": "2.0.0",
                                    "inlineScript": "/**\n * @param {params} params\n * @param {api} params.api\n * @param {TransformApiHelpers} params.helpers\n */\nfunction evaluateProperty({\n    api,\n    helpers\n}) {\n    return !((api.context.props.table === \"kb_knowledge\" || api.context.props.table.startsWith(\"kb_template\") || api.context.props.table.startsWith(\"u_kb_template\")) && api.data.plugin_status_1.output.active);\n}",
